(() => {
  "use strict";
  const VERSION = "62";
  const DATA = [{"name":"Agus Halim","period":"1980–1984","image":"data:image/webp;base64,","current":false},{"name":"Sukmo","period":"1984–1989","image":"data:image/webp;base64,","current":false},{"name":"Rudiman","period":"1989–1996","image":"data:image/webp;base64,","current":false},{"name":"Drs. H. Sadimin","period":"1996–2003","image":"data:image/webp;base64,","current":false},{"name":"Drs. Slamet AY","period":"2003–2006","image":"data:image/webp;base64,","current":false},{"name":"Pujianti, S.Pd.","period":"2006–2010","image":"data:image/webp;base64,","current":false},{"name":"Rokhndayani, S.Pd., M.Pd.","period":"2010–2012","image":"data:image/webp;base64,","current":false},{"name":"Erry Subekti, S.Pd., M.M.","period":"2012–2014","image":"data:image/webp;base64,","current":false},{"name":"Bambang Kuseno, S.Pd.","period":"2014–2016","image":"data:image/webp;base64,","current":false},{"name":"Rojat, S.Pd.","period":"2016–2024","image":"data:image/webp;base64,","current":false},{"name":"Drs. H. Akhmad Samiri, M.Pd.","period":"2024–2026","image":"data:image/webp;base64,","current":false},{"name":"Hari Teguh Wibowo, S.Pd., M.Si.","period":"2026–sekarang","image":"data:image/webp;base64,","current":true}];
  const $ = (selector, root = document) => root?.querySelector?.(selector) || null;
  const $$ = (selector, root = document) => [...(root?.querySelectorAll?.(selector) || [])];
  const escapeHtml = (value) => String(value ?? "").replace(/[&<>"']/g, (character) => ({
    "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#039;"
  })[character]);

  function cardsHtml() {
    return DATA.map((item, index) => `
      <article class="v62-headmaster-card${item.current ? " is-current" : ""}" aria-label="${escapeHtml(item.name)}, masa jabatan ${escapeHtml(item.period)}">
        <div class="v62-headmaster-order" aria-hidden="true">${String(index + 1).padStart(2, "0")}</div>
        ${item.current ? '<div class="v62-current-badge">MENJABAT SEKARANG</div>' : ""}
        <figure class="v62-headmaster-photo">
          <img src="${item.image}" alt="Foto ${escapeHtml(item.name)}" ${index < 4 ? 'loading="eager" fetchpriority="high"' : 'loading="lazy"'} decoding="async">
        </figure>
        <div class="v62-headmaster-info">
          <span>${item.current ? "KEPALA SEKOLAH SAAT INI" : "MASA JABATAN"}</span>
          <h3>${escapeHtml(item.name)}</h3>
          <p>${escapeHtml(item.period)}</p>
        </div>
      </article>`).join("");
  }

  function activate(name) {
    $$('[data-about-tab]').forEach((button) => {
      const active = button.dataset.aboutTab === name;
      button.setAttribute("aria-pressed", String(active));
      button.classList.toggle("is-active", active);
    });
    $$('[data-about-panel]').forEach((panel) => {
      panel.hidden = panel.dataset.aboutPanel !== name;
    });
  }

  function buildOrRepairPanel() {
    const tabs = $(".about-tabs-v29");
    const profilePanel = $("[data-about-panel='profile']");
    if (!tabs || !profilePanel) return;

    let button = $("[data-about-tab='headmasters']", tabs);
    if (!button) {
      button = document.createElement("button");
      button.type = "button";
      button.dataset.aboutTab = "headmasters";
      button.setAttribute("aria-pressed", "false");
      button.textContent = "Kepala Sekolah dari Masa ke Masa";
      const teacherButton = $("[data-about-tab='teachers']", tabs);
      tabs.insertBefore(button, teacherButton || null);
    }

    let panel = $("[data-about-panel='headmasters']");
    if (!panel) {
      panel = document.createElement("section");
      panel.className = "about-panel-v29";
      panel.dataset.aboutPanel = "headmasters";
      panel.hidden = true;
      const teacherPanel = $("[data-about-panel='teachers']");
      teacherPanel?.parentElement?.insertBefore(panel, teacherPanel);
    }

    panel.classList.remove("v61-headmasters-panel");
    panel.classList.add("v62-headmasters-panel");
    panel.innerHTML = `
      <header class="v62-headmasters-hero">
        <div><span>JEJAK KEPEMIMPINAN SPENSUS</span><h2>Kepala Sekolah dari Masa ke Masa</h2><p>Perjalanan kepemimpinan SMP Negeri 1 Susukan ditampilkan berurutan sejak sekolah berdiri hingga kepala sekolah yang menjabat sekarang.</p></div>
        <b>1980–sekarang</b>
      </header>
      <div class="v62-headmasters-grid">${cardsHtml()}</div>`;

    const cleanButton = button.cloneNode(true);
    button.replaceWith(cleanButton);
    cleanButton.addEventListener("click", () => {
      activate("headmasters");
      panel.scrollIntoView({ block:"start", behavior:"smooth" });
    });

    $$('[data-about-tab]:not([data-about-tab="headmasters"])', tabs).forEach((item) => {
      if (item.dataset.v62Bound === "yes") return;
      item.dataset.v62Bound = "yes";
      item.addEventListener("click", () => activate(item.dataset.aboutTab));
    });

    document.documentElement.dataset.headmastersV62 = VERSION;
  }

  function init() {
    if (!/about-spensus\.html$/i.test(location.pathname)) return;
    buildOrRepairPanel();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init, { once:true });
  else init();
})();
